def parse_duration(s: str) -> int:
    if not s:
        raise ValueError

    unit_idx = {'d': 0, 'h': 1, 'm': 2, 's': 3}
    mult = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    last = -1
    total = 0
    i = 0
    n = len(s)

    while i < n:
        if not s[i].isdigit():
            raise ValueError

        num = 0
        while i < n and s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1

        if i >= n or s[i] not in unit_idx:
            raise ValueError

        u = s[i]
        i += 1
        cidx = unit_idx[u]

        if cidx <= last:
            raise ValueError

        last = cidx
        total += num * mult[u]

    return total
```

