def calc(expr: str) -> float:
    s = expr.replace(' ', '')
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] in '+-*/()':
            tokens.append(s[i])
            i += 1
        elif s[i].isdigit() or s[i] == '.':
            j = i
            while j < n and (s[j].isdigit() or s[j] == '.'):
                j += 1
            tokens.append(float(s[i:j]))
            i = j
        else:
            i += 1

    pos = 0
    m = len(tokens)

    def peek():
        if pos < m:
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        pos += 1

    def parse_expr():
        nonlocal pos
        left = parse_term()
        while peek() in ('+', '-'):
            op = peek()
            consume()
            right = parse_term()
            if op == '+':
                left += right
            else:
                left -= right
        return left

    def parse_term():
        nonlocal pos
        left = parse_factor()
        while peek() in ('*', '/'):
            op = peek()
            consume()
            right = parse_factor()
            if op == '*':
                left *= right
            else:
                left /= right
        return left

    def parse_factor():
        nonlocal pos
        if peek() in ('+', '-'):
            op = peek()
            consume()
            right = parse_factor()
            return -right if op == '-' else right
        if peek() == '(':
            consume()  # consume '('
            result = parse_expr()
            if peek() == ')':
                consume()  # consume ')'
            return result
        # number
        val = peek()
        consume()
        return val

    pos = 0
    return parse_expr()
```

