from collections import deque

class SlidingWindowLimiter:
    def __init__(self, limit: int, window: float):
        self.limit = limit
        self.window = window
        self.key_timestamps = {}

    def allow(self, key: str, now: float) -> bool:
        dq = self.key_timestamps.get(key)
        if dq is None:
            dq = deque()
            self.key_timestamps[key] = dq
        # Remove timestamps that fall outside the half-open interval (now - window, now]
        while dq and dq[0] <= now - self.window:
            dq.popleft()
        if len(dq) < self.limit:
            dq.append(now)
            return True
        return False
```

