def bill(kwh: float) -> float:
    TIERS = [(100, 0.10), (300, 0.15), (float('inf'), 0.20)]
    total = 0.0
    prev = 0
    for limit, rate in TIERS:
        if kwh <= prev:
            break
        if limit == float('inf'):
            chargeable = kwh - prev
        else:
            chargeable = min(kwh - prev, limit - prev)
        total += chargeable * rate
        prev = limit
    return round(total, 2)
```

